            if comp:
                components.append(comp)

    bboxes = []
    for comp in components:
        rows = [p[0] for p in comp]
        cols = [p[1] for p in comp]
        bboxes.append((min(rows), max(rows), min(cols), max(cols)))

    return bboxes

def transform_correct(grid):
    color_map = {0:0, 1:1, 2:3, 3:8, 4:7, 5:4, 6:4, 7:3, 8:3}

    bboxes = find_yellow_bboxes(grid)
    if not bboxes:
        return [[color_map.get(grid[r][c], grid[r][c]) for c in range(len(grid[0]))] for r in range(len(grid))]

    result = [[color_map.get(grid[r][c], grid[r][c]) for c in range(len(grid[0]))] for r in range(len(grid))]

    for bbox in bboxes:
        min_r, max_r, min_c, max_c = bbox

        # Adjacent cells OUTSIDE all bboxes (use min_r-1, max_r+1, etc.)
        adj_above = [grid[min_r - 1][c] for c in range(min_c, max_c + 1)]
        adj_below = [grid[max_r + 1][c] for c in range(min_c, max_c + 1)]
        adj_left = [grid[r][min_c - 1] for r in range(min_r, max_r + 1)]
        adj_right = [grid[r][max_c + 1] for r in range(min_r, max_r + 1)]

        adj_mode = max(set(adj_above + adj_below + adj_left + adj_right), key=lambda x: (adj_above + adj_below + adj_left + adj_right).count(x))

        print(f"adj_mode for bbox {bbox}: {adj_mode}")

        # Transform interior cells (strictly inside bbox, not on edge)
        for r in range(min_r + 1, max_r):  # min_r+1 to max_r-1
            for c in range(min_c + 1, max_c):  # min_c+1 to max_c-1
                cell = grid[r][c]

                if cell == 4:
                    result[r][c] = adj_mode
                elif cell == 3:
                    # 3→2 when adj_mode in [2, 0]
                    if adj_mode in [2, 0]:
                        result[r][c] = 2
                    else:
                        result[r][c] = adj_mode
                else:
                    result[r][c] = adj_mode

    return result

